sys_script_client.script:
// This script sets 'assigned_to' to the current user if it's empty

function onLoad() {

    var groupSysId = g_form.getValue('assignment_group');
    var isAssigned = g_form.getValue('assigned_to');
    var cat = g_form.getValue('category_aml');
    var state = g_form.getValue('state');
    //MSSTRUSTES-355
    if (!isAssigned && groupSysId) {
        g_form.setValue('assigned_to', g_user.userID);
        if (cat == 'new_enrollment' && state == '1') {
            g_form.setValue('state', '2');
        } else if ((cat == 'periodic_review_query' || cat.includes('rule')) && state == '1') {
            g_form.setValue('state', '-5');
        }
        g_form.save();
        return;
    }
}
